import{_ as a,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Kubernetes Stateful Application Disaster Recovery with Zero Data Loss - Daniel Parkes, IBM","description":"","frontmatter":{"title":"Kubernetes Stateful Application Disaster Recovery with Zero Data Loss - Daniel Parkes, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Kubernetes","灾难恢复","Ceph","同步复制","状态应用"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Kubernetes_Stateful_Application_Disaster_Recovery_with_Zero_Data_Loss_-_Daniel_Parkes_IBM.md","filePath":"posts/2023/Kubernetes_Stateful_Application_Disaster_Recovery_with_Zero_Data_Loss_-_Daniel_Parkes_IBM.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Kubernetes_Stateful_Application_Disaster_Recovery_with_Zero_Data_Loss_-_Daniel_Parkes_IBM.md"};function s(o,e,n,_,u,h){return l(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-kubernetes中状态应用的同步复制策略" tabindex="-1">会议主题：Kubernetes中状态应用的同步复制策略 <a class="header-anchor" href="#会议主题-kubernetes中状态应用的同步复制策略" aria-label="Permalink to &quot;会议主题：Kubernetes中状态应用的同步复制策略&quot;">​</a></h4><h4 id="主讲人-daniel-parks-ibm产品管理团队" tabindex="-1">主讲人：Daniel Parks（IBM产品管理团队） <a class="header-anchor" href="#主讲人-daniel-parks-ibm产品管理团队" aria-label="Permalink to &quot;主讲人：Daniel Parks（IBM产品管理团队）&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>背景介绍</strong>：</p><ul><li>Daniel Parks介绍了在Kubernetes中运行关键应用的需求日益增长，这些应用需要持久化数据，因此对数据复制（DR）的需求也在增加。</li><li>讨论了不同类型的数据复制选项，包括备份与恢复、异步复制和同步复制（Metro DR）。</li></ul></li><li><p><strong>备份与恢复</strong>：</p><ul><li>使用Velero API进行备份和恢复，适用于逻辑故障的覆盖，但RPO（恢复点目标）和RTO（恢复时间目标）容忍度较高。</li></ul></li><li><p><strong>异步复制（区域DR）</strong>：</p><ul><li>使用Open Cluster Manager进行应用的故障转移和恢复，RPO在几分钟范围内，RTO依赖于应用启动时间等因素。</li></ul></li><li><p><strong>同步复制（地铁DR）</strong>：</p><ul><li>提供了零数据丢失的同步复制解决方案，主要依赖于Ceph的stretch模式。</li><li>使用Rook在Kubernetes集群中部署Ceph，并通过RBD镜像进行块卷的同步复制。</li><li>需要低延迟（约10毫秒）以保证性能，适用于非常关键的应用。</li></ul></li><li><p><strong>Ceph Stretch模式</strong>：</p><ul><li>讨论了Ceph在stretch模式下的部署细节，包括使用Arbiter节点作为仲裁者，确保在网络分区情况下仍能维持高可用性。</li><li>强调了在这种模式下，Ceph集群的自动调整和恢复机制。</li></ul></li><li><p><strong>应用故障转移演示</strong>：</p><ul><li>展示了如何在Open Cluster Manager中进行应用的故障转移和恢复，确保RPO为零，没有数据丢失。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认了同步复制（Metro DR）作为关键应用的高可用性解决方案。</li><li>讨论了Ceph在stretch模式下的部署和操作细节。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续优化和测试同步复制解决方案，确保其在实际应用中的稳定性和性能。</li><li>探索更多自动化选项，以减少手动操作在故障转移过程中的需求。</li><li>提供更多文档和资源，帮助用户理解和部署这些高可用性解决方案。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点： <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点：&quot;">​</a></h4><ul><li>讨论了CFS（Ceph File System）在同步复制中的应用潜力和可能的改进。</li><li>确认了所有演示和讨论的组件均为开源项目，鼓励社区参与和贡献。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在感谢和掌声中结束，Daniel Parks鼓励大家如果有任何问题或需要进一步的信息，可以随时联系。</li></ul><p>[改进后的总结包含以下Ceph相关关键词]：</p><ul><li>Ceph</li><li>stretch模式</li><li>Rook</li><li>RBD</li><li>Open Cluster Manager</li><li>Metro DR</li><li>同步复制 -灾难恢复 -高可用性</li></ul>',15)])])}const d=a(r,[["render",s]]);export{c as __pageData,d as default};
